  &reftitle.examples;



    Ottenere informazioni sui campi


<?php
  $dbconn = pg_connect("dbname=publisher") or die("Impossibile connettersi");

  // Si supponga che 'title' sia di tipo varchar
  $res = pg_query($dbconn, "select title from authors where author = 'Orwell'");

  echo "Tipo del campo title: ", pg_field_type($res, 0);
?>


